import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [formData, setFormData] = useState({ name: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });

  const fetchTeachers = () => {
    axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data)).catch(err => console.error(err));
  };

  useEffect(() => { fetchTeachers(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-teacher', formData).then(res => {
        if(res.data.status === "Success") {
            fetchTeachers(); 
            setFormData({ name: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });
            setShowAddForm(false);
            alert("✅ Lecturer added successfully!");
        }
      });
  };

  return (
    <div style={{ padding: '30px', backgroundColor: '#f8fafc', minHeight: '100vh', position: 'relative' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
        <h2 style={{ color: '#15803d', margin: 0 }}>Manage Teachers</h2>
        <button onClick={() => setShowAddForm(true)} style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Add New Teacher</button>
      </div>
      
      {showAddForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '12px', width: '500px', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' }}>
            <h3 style={{ marginTop: 0, color: '#334155', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>Add New Teacher</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' }}>
              <input type="text" placeholder="Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              <select value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} required style={inputStyle}>
                  <option value="" disabled>-- Select Teaching Subject --</option>
                  <option value="Mathematics">Mathematics</option><option value="Science">Science</option><option value="English">English</option><option value="Combined Maths">Combined Maths</option><option value="Biology">Biology</option><option value="Physics">Physics</option><option value="Chemistry">Chemistry</option>
              </select>
              <input type="text" placeholder="Qualifications (e.g. B.Sc, M.Ed)" value={formData.qualifications} onChange={(e) => setFormData({...formData, qualifications: e.target.value})} style={inputStyle} />
              <input type="email" placeholder="Email Address" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} style={inputStyle} />
              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} style={inputStyle} />
              <input type="text" placeholder="Residence Address" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
              <div style={{ backgroundColor: '#f0fdf4', padding: '10px', borderRadius: '8px', border: '1px dashed #22c55e', fontSize: '12px', color: '#15803d' }}>Default password: <b>TC@123</b></div>
              <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={() => setShowAddForm(false)} style={{ flex: 1, padding: '12px', backgroundColor: '#e2e8f0', color: '#334155', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Cancel</button>
                <button type="submit" style={{ flex: 1, padding: '12px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Save Teacher</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div style={{ backgroundColor: 'white', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', overflow: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '900px' }}>
          <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
            <tr><th style={thStyle}>Full Name</th><th style={thStyle}>Subject</th><th style={thStyle}>Qualifications</th><th style={thStyle}>Email</th><th style={thStyle}>Phone</th><th style={thStyle}>Address</th></tr>
          </thead>
          <tbody>
            {teachers.length > 0 ? teachers.map((t) => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9' }}><td style={tdStyle}><b>{t.name}</b></td><td style={tdStyle}>{t.subject}</td><td style={tdStyle}>{t.qualifications || '-'}</td><td style={tdStyle}>{t.email || '-'}</td><td style={tdStyle}>{t.phone_number || '-'}</td><td style={tdStyle}>{t.address || '-'}</td></tr>
            )) : <tr><td colSpan="6" style={{ padding: '20px', textAlign: 'center', color: '#ef4444' }}>No teachers found.</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}
const inputStyle = { padding: '12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', fontSize: '14px', whiteSpace: 'nowrap' };
const tdStyle = { padding: '15px', fontSize: '14px', color: '#475569' };
